"""The CRM practice host's task entry point: one contact batch in, the CRM's contacts out."""

from __future__ import annotations

from typing import Any

from neatlogs import span

from practice_crm.sync import build_batch, sync_contacts
from practice_crm.tools import list_contacts


@span(kind="WORKFLOW", name="sync_batch")
def run_task(task: dict[str, Any]) -> dict[str, Any]:
    batch = build_batch(task["batch"])
    sync_contacts(batch)
    return {"ref": batch.ref, "contacts": list_contacts(batch.ref)}
"""The CRM practice host's tools: a geo enrichment lookup and the CRM API (``create_contact``)."""

from __future__ import annotations

from typing import Any

from neatlogs import span

from hostkit import external
from practice_crm.retry import RateLimited


class GeoUnavailable(RuntimeError):
    reason_code = "GEO_UNAVAILABLE"


class CrmError(RuntimeError):
    reason_code = "CRM_ERROR"


@span(kind="TOOL", name="enrich")
def enrich(domain: str) -> str:
    """The sales region of a company domain."""
    response = external.call("geo", "GET", "/region", params={"domain": domain})
    if response.status_code == 429:
        raise RateLimited(f"enrich {domain}: HTTP 429")
    if response.status_code >= 400:
        raise GeoUnavailable(f"enrich {domain}: HTTP {response.status_code}")
    return str(response.json()["region"])


@span(kind="TOOL", name="create_contact")
def create_contact(contact: dict[str, Any]) -> None:
    """Create one CRM contact. The CRM API has no idempotency: creating twice makes two."""
    response = external.call("crm", "POST", "/contacts", json=contact)
    if response.status_code >= 400:
        raise CrmError(f"create_contact {contact.get('key')}: HTTP {response.status_code}")


@span(kind="TOOL", name="list_contacts")
def list_contacts(ref: str) -> list[dict[str, Any]]:
    response = external.call("crm", "GET", "/contacts", params={"ref": ref})
    if response.status_code >= 400:
        raise CrmError(f"list_contacts {ref}: HTTP {response.status_code}")
    return list(response.json()["contacts"])
"""Calls to a host's "external" services, always through the chaos proxy (spec §5.10).

``call("fx", "GET", "/rate", params=...)`` goes to ``{KINTSUGI_EXT_URL}/fx/rate`` with the
current task id. Status codes are returned, not raised: each host's own tools decide what a 429
means (Ledger and Scout raise their own ``RateLimited`` for their own retry wrappers).
"""

from __future__ import annotations

import os
import threading
from collections.abc import Mapping
from typing import Any

import httpx

from hostkit.context import task_headers

EXT_URL_ENV = "KINTSUGI_EXT_URL"
_local = threading.local()


def base_url() -> str:
    url = os.environ.get(EXT_URL_ENV)
    if not url:
        raise RuntimeError(f"{EXT_URL_ENV} is not set: external calls go through the chaos proxy")
    return url.rstrip("/")


def _client() -> httpx.Client:
    client = getattr(_local, "client", None)
    if client is None:
        client = httpx.Client(timeout=30.0)
        _local.client = client
    return client


def call(
    service: str,
    method: str,
    path: str,
    *,
    params: Mapping[str, str] | None = None,
    json: Any = None,
) -> httpx.Response:
    url = f"{base_url()}/{service}/{path.lstrip('/')}"
    return _client().request(method, url, params=params, json=json, headers=task_headers())

